// PROTOTYPE. TS back end: one module per Shared Adapter per side, calling runtime/ts/core.ts.
// Output shapes (the Host glue adapts them):
//   makeRequests(req) -> { body?, impIDs?, errs }
//   makeBids(req, resp) -> { bids: [{ bid, type, seat, dealPriority, video, meta }], currency, paapi, errs }
const ID = /^[A-Za-z_$][A-Za-z0-9_$]*$/;
const q = JSON.stringify;

function exprTs(e, sc) {
  const x = (e) => exprTs(e, sc);
  switch (e.k) {
    case 'lit': return q(e.v);
    case 'absent': return 'undefined';
    case 'keep': throw new Error('keep is only valid as the value (or a branch) of a set rule');
    case 'var': {
      const v = sc.vars[e.name];
      if (!v) throw new Error(`unknown name ${e.name}`);
      return v;
    }
    case 'get': return `${x(e.e)}?.${ID.test(e.key) ? e.key : `[${q(e.key)}]`}`;
    case 'at': return `${x(e.e)}?.[${e.i}]`;
    case 'index':
      if (e.e.k !== 'obj') throw new Error('computed index is only supported on a lookup table literal');
      return `r.lk(${x(e.e)}, ${x(e.i)})`;
    case 'not': return `!${x(e.e)}`;
    case 'cond': return `(${x(e.c)} ? ${x(e.a)} : ${x(e.b)})`;
    case 'bin': {
      const [l, rr] = [x(e.l), x(e.r)];
      if (e.op === '==' || e.op === '!=') {
        const loose = (e.l.k === 'lit' && e.l.v === null) || (e.r.k === 'lit' && e.r.v === null);
        return `(${l} ${loose ? e.op : e.op + '='} ${rr})`;
      }
      if (['<', '>', '<=', '>=', '+', '-'].includes(e.op)) return `(r.n(${l}) ${e.op} r.n(${rr}))`;
      return `(${l} ${e.op} ${rr})`;
    }
    case 'call': return `r.${e.fn}(${e.args.map(x).join(', ')})`;
    case 'macro': {
      const v = `x_${e.v}`;
      const body = exprTs(e.body, { vars: { ...sc.vars, [e.v]: v } });
      if (e.name === 'map') return `r.map(${x(e.recv)}, (${v}) => (${body}))`;
      return `r.arr(${x(e.recv)}).${e.name}((${v}) => (${body}))`;
    }
    case 'obj': return `{ ${e.entries.map(([k, v]) => `${ID.test(k) ? k : q(k)}: ${x(v)}`).join(', ')} }`;
    case 'arr': return `r.arrLit([${e.items.map((i) => (i.spread ? `...r.arr(${x(i.e)})` : x(i.e))).join(', ')}])`;
    case 'tmpl': return '`' + e.parts.map((p) => (typeof p === 'string' ? p.replace(/[`\\$]/g, '\\$&') : '${r.s(' + x(p) + ')}')).join('') + '`';
  }
  throw new Error('unhandled ' + e.k);
}

// A set rule: `keep` branches become control flow; `?` segments guard on existence in the output;
// 'add' rules (Extensions) only write when the output has nothing there yet.
function setTs(target, path, e, mode, sc, ind) {
  const keys = path.map((s) => s.key);
  const guards = [];
  path.forEach((s, i) => s.opt && guards.push(`r.get(${target}, ${q(keys.slice(0, i + 1))}) != null`));
  if (mode === 'add') guards.push(`r.get(${target}, ${q(keys)}) === undefined`);
  const body = (e) => {
    if (e.k === 'keep') return '';
    if (e.k === 'cond' && hasKeep(e)) {
      const a = body(e.a), b = body(e.b);
      return `if (${exprTs(e.c, sc)}) {${a}} else {${b}}`;
    }
    return `${target} = r.put(${target}, ${q(keys)}, ${exprTs(e, sc)});`;
  };
  const b = body(e);
  return ind + (guards.length ? `if (${guards.join(' && ')}) { ${b} }` : b) + '\n';
}
const hasKeep = (e) => e.k === 'keep' || (e.k === 'cond' && (hasKeep(e.a) || hasKeep(e.b)));

function lets(ls, sc, ind) {
  let s = '';
  for (const [n, e] of ls) {
    const v = `v_${n}`;
    s += `${ind}const ${v} = ${exprTs(e, sc)};\n`;
    sc.vars[n] = v;
  }
  return s;
}

export function emitTs(m, runtimePath) {
  let s = `// GENERATED by the PROTOTYPE Definition Compiler from defs/${m.bidder}.yaml - do not edit.\n`;
  s += `import * as r from '${runtimePath}';\n\n`;
  s += `export const bidder = ${q(m.bidder)};\nexport const endpoint = ${q(m.endpoint)};\n\n`;

  // ---- makeRequests ----
  let sc = { vars: { req: 'req' } };
  s += `export function makeRequests(req: any): any {\n  const errs: string[] = [], imps: any[] = [], params: any[] = [];\n`;
  s += `  for (const imp of r.arr(req.imp)) {\n    const p = imp?.ext?.bidder;\n`;
  const isc = { vars: { ...sc.vars, imp: 'imp', p: 'p' } };
  s += lets(m.imp.lets, isc, '    ');
  for (const [c, msg] of m.imp.checks) s += `    if (${exprTs(c, isc)}) { errs.push(${exprTs(msg, isc)}); continue; }\n`;
  for (const d of m.imp.drops) s += `    if (${exprTs(d, isc)}) continue;\n`;
  s += `    let o = imp;\n`;
  for (const [p, e, mode] of m.imp.sets) s += setTs('o', p, e, mode, isc, '    ');
  s += `    imps.push(o); params.push(p);\n  }\n  if (!imps.length) return { errs };\n`;
  const rsc = { vars: { ...sc.vars, imps: 'imps', params: 'params' } };
  s += lets(m.request.lets, rsc, '  ');
  s += `  let o = r.put(req, ['imp'], imps);\n`;
  for (const [p, e, mode] of m.request.sets) s += setTs('o', p, e, mode, rsc, '  ');
  s += `  return { body: o, impIDs: imps.map((i) => i.id), errs };\n}\n\n`;

  // ---- makeBids ----
  s += `export function makeBids(req: any, resp: any): any {\n  const errs: string[] = [], bids: any[] = [];\n`;
  s += `  for (const seatbid of r.arr(resp?.seatbid)) for (const bid of r.arr(seatbid?.bid)) {\n`;
  s += `    const imp = r.arr(req?.imp).find((i) => i?.id === bid?.impid);\n`;
  const bsc = { vars: { req: 'req', resp: 'resp', seatbid: 'seatbid', bid: 'bid', imp: 'imp' } };
  s += lets(m.bid.lets, bsc, '    ');
  for (const [c, msg] of m.bid.checks) s += `    if (${exprTs(c, bsc)}) { errs.push(${exprTs(msg, bsc)}); continue; }\n`;
  for (const [c, msg] of m.bid.warns) s += `    if (${exprTs(c, bsc)}) errs.push(${exprTs(msg, bsc)});\n`;
  for (const d of m.bid.drops) s += `    if (${exprTs(d, bsc)}) continue;\n`;
  s += `    let o = bid;\n`;
  for (const [p, e, mode] of m.bid.sets) s += setTs('o', p, e, mode, bsc, '    ');
  const f = m.bidFields;
  const fe = (k) => (f[k] ? exprTs(f[k], bsc) : 'undefined');
  s += `    bids.push({ bid: o, type: ${fe('type')}, seat: ${fe('seat')}, dealPriority: ${fe('dealPriority')}, video: ${fe('video')}, meta: ${fe('meta')} });\n  }\n`;
  const psc = { vars: { req: 'req', resp: 'resp' } };
  s += `  return { bids, currency: ${exprTs(m.response.currency, psc)}, paapi: ${exprTs(m.response.paapi, psc)}, errs };\n}\n`;
  return s;
}
